-- Extends current exact bundle fixture, never a live Google profile.
select public.record_agency_verification('rr-other@example.test','99100000-0000-4000-8000-000000000012','google','verified','{"note":"fictional maintenance"}',null);
insert into public.workspace_account_bindings(id,workspace_id,provider,scopes,status,migrated_from) values('99100000-0000-4000-8000-000000000201','99100000-0000-4000-8000-000000000011','google',array['https://www.googleapis.com/auth/business.manage'],'connected','oauth');
insert into public.workspace_google_locations(workspace_id,binding_id,account_id,location_id) values('99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','accounts/fictional','location');
select public.grant_client_resource_mandate('99100000-0000-4000-8000-000000000001','rr-owner@example.test','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000012','google','google_location','location');
update public.service_requests set context=context||jsonb_build_object('maintenanceAttachment',jsonb_build_object('bindingId','99100000-0000-4000-8000-000000000201','locationId','location','hoursSource','business_record','replyPolicy','approve')) where id='99100000-0000-4000-8000-000000000021';
insert into public.business_records(workspace_id,created_by,updated_by) values('99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000001','99100000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.business_record_facts(workspace_id,fact_key,value,source,updated_by) values('99100000-0000-4000-8000-000000000011','hours','{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}','owner','99100000-0000-4000-8000-000000000001');
create temp table bm_attachment as select public.attach_keep_me_found_maintenance('99100000-0000-4000-8000-000000000001','rr-owner@example.test',(select (result->>'bundleId')::uuid from rr_created),'99100000-0000-4000-8000-000000000201','location','business_record','approve') result;
select pg_temp.assert_ok((result->>'providerWorkspaceId')::uuid='99100000-0000-4000-8000-000000000012' and result->>'replyPolicy'='approve','actual agency and human approval contract') from bm_attachment;
select pg_temp.assert_ok(public.create_keep_me_found_maintenance_bundle('99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000021','99100000-0000-4000-8000-000000000012','99100000-0000-4000-8000-000000000001','rr-owner@example.test','bundle:1',investigations,604800,next_at,'99100000-0000-4000-8000-000000000201','location')->'maintenance'->>'attachmentId'=(select result->>'attachmentId' from bm_attachment),'one-action wrapper exact replay preserves attachment and five policies') from rr_input;
insert into public.service_requests(id,business_workspace_id,status,request_text,outcome,context,scope,provider_kind,provider_agency_workspace_id,provider_acceptance,accepted_by,accepted_at,created_by,delivery_commitment)
select '99100000-0000-4000-8000-000000000022',business_workspace_id,status,request_text,outcome,jsonb_set(context,'{maintenanceAttachment,locationId}','"unowned"'),scope,provider_kind,provider_agency_workspace_id,provider_acceptance,accepted_by,accepted_at,created_by,delivery_commitment from public.service_requests where id='99100000-0000-4000-8000-000000000021';
select pg_temp.expect_fail(format('select public.create_keep_me_found_maintenance_bundle(%L,%L,%L,%L,%L,%L,%L::jsonb,604800,%L::timestamptz,%L,%L)','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000022','99100000-0000-4000-8000-000000000012','99100000-0000-4000-8000-000000000001','rr-owner@example.test','bundle:bad',investigations,next_at,'99100000-0000-4000-8000-000000000201','unowned'),'acting_provider_no_mandate') from rr_input;
select pg_temp.assert_ok((select count(*)=5 from public.standing_responsibilities where workspace_id='99100000-0000-4000-8000-000000000011') and (select count(*)=1 from public.responsibility_bundles where business_workspace_id='99100000-0000-4000-8000-000000000011'),'failed one-action attachment rolls back the entire new bundle');
create temp table bm_prepared as select public.reserve_bundle_maintenance_preparation((result->>'attachmentId')::uuid,'99100000-0000-4000-8000-000000000002','rr-agency@example.test','cycle:1',0,'{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}') result from bm_attachment;
select pg_temp.assert_ok(result->>'replayed'='false' and result->>'prepared_by'='99100000-0000-4000-8000-000000000002','agency prepares under own identity') from bm_prepared;
select public.link_bundle_maintenance_event((result->>'id')::uuid,'99100000-0000-4000-8000-000000000002','rr-agency@example.test','fictional-exact-event') from bm_prepared;
select pg_temp.assert_ok(public.check_bundle_maintenance_event((result->>'id')::uuid,'fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location','{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}'),'native dispatch pin rechecked, no provider call') from bm_prepared;
select pg_temp.expect_fail('update public.bundle_maintenance_preparations set draft=''{}''','snapshot_immutable');
select pg_temp.expect_fail('delete from public.bundle_maintenance_attachments','snapshot_immutable');
select pg_temp.assert_ok(not has_table_privilege('service_role','public.bundle_maintenance_preparations','INSERT') and not has_function_privilege('authenticated','public.check_bundle_maintenance_event(uuid,text,uuid,uuid,text,jsonb)','EXECUTE'),'service-only RPC and denied table mutation');
select pg_temp.expect_fail(format('select public.reserve_bundle_maintenance_preparation(%L,%L,%L,%L,0,%L::jsonb)',result->>'attachmentId','99100000-0000-4000-8000-000000000001','rr-owner@example.test','cycle:owner','{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}'),'acting_provider_not_staffed') from bm_attachment;
select pg_temp.expect_fail(format('select public.reserve_bundle_maintenance_preparation(%L,%L,%L,%L,1,%L::jsonb)',result->>'attachmentId','99100000-0000-4000-8000-000000000002','rr-agency@example.test','cycle:stale','{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}'),'source_changed') from bm_attachment;
select pg_temp.assert_ok(public.reserve_bundle_maintenance_preparation((result->>'attachmentId')::uuid,'99100000-0000-4000-8000-000000000002','rr-agency@example.test','cycle:1',0,'{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}')->>'eventId'='fictional-exact-event','same preparation/event exact replay') from bm_attachment;
select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000031','99100000-0000-4000-8000-000000000201','location','{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}'),'event_changed') from bm_prepared;
savepoint source_change;
update public.business_records set revision=revision+1 where workspace_id='99100000-0000-4000-8000-000000000011';
select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location',result->'draft'),'source_changed') from bm_prepared;
rollback to source_change;
savepoint scope_change;
