select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location',result->'draft'),'mandate_revoked') from bm_prepared;
rollback to delivery_missing;
