select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location',result->'draft'),'paused') from bm_prepared;
rollback to paused;
savepoint owner_lost;
update public.users set verified_at=null where id='99100000-0000-4000-8000-000000000001';
select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location',result->'draft'),'owner_changed') from bm_prepared;
rollback to owner_lost;
savepoint version_changed;
select public.update_standing_responsibility(s.id,s.workspace_id,s.owner_id,'rr-owner@example.test',s.revision,s.payload||jsonb_build_object('revision',s.revision+1,'status','paused','history',(s.payload->'history')||jsonb_build_array(jsonb_build_object('revision',s.revision+1,'kind','pause','actorId',s.owner_id,'at',clock_timestamp(),'detail','Version-change fixture')))) from public.standing_responsibilities s join public.responsibility_bundle_members m on m.standing_responsibility_id=s.id where m.responsibility_key='hours_sync';
select public.update_standing_responsibility(s.id,s.workspace_id,s.owner_id,'rr-owner@example.test',s.revision,(s.payload-'approvedBy'-'approvedAt')||jsonb_build_object('version',s.version+1,'revision',s.revision+1,'status','proposed','history',(s.payload->'history')||jsonb_build_array(jsonb_build_object('revision',s.revision+1,'kind','update','actorId',s.owner_id,'at',clock_timestamp(),'detail','Changed approved Version fixture')))) from public.standing_responsibilities s join public.responsibility_bundle_members m on m.standing_responsibility_id=s.id where m.responsibility_key='hours_sync';
select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location',result->'draft'),'source_changed') from bm_prepared;
rollback to version_changed;
update public.service_requests set provider_acceptance='pending',accepted_by=null,accepted_at=null where id='99100000-0000-4000-8000-000000000021';
select pg_temp.expect_fail(format('select public.check_bundle_maintenance_event(%L,%L,%L,%L,%L,%L::jsonb)',result->>'id','fictional-exact-event','99100000-0000-4000-8000-000000000011','99100000-0000-4000-8000-000000000201','location','{"action":"hours","hours":{"timezone":"America/New_York","weekly":[{"day":1,"opens":"09:00","closes":"17:00"}]}}'),'mandate_revoked') from bm_prepared;
rollback;
